import re

def anti_shuffle(s):
    tokens = re.findall(r'\S+|\s+', s)
    for i in range(len(tokens)):
        if tokens[i].isspace():
            continue
        tokens[i] = ''.join(sorted(tokens[i]))
    return ''.join(tokens)
